1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
misc: remove double-semicolons

The previous commit 9ef80aefd354 ("hawkbit: fix process notification not
sending logs") introduced a typo using two semicolons after a statement.

While looking I also found another one.

This is not harmful, but is bad style: remove them.

Signed-off-by: Dominique Martinet <dominique.martinet@atmark-techno.com>

Here is the root cause:
The root cause of the bug was the introduction of double semicolons (`;;`) after statements in the code, which, while not harmful, is considered bad style and can lead to confusion or misinterpretation of the code's intent. This issue was likely introduced in a previous commit and was identified during a review of the code.

Here is the patch:

 static void *process_notification_thread(void *data)
 {
 	const int action_id = *(int *)data;
 	const int MAX_DETAILS = 48;
 	const char *details[MAX_DETAILS];
 	unsigned int numdetails = 0;
 	bool stop = false;
 	channel_data_t channel_data = channel_data_defaults;
 	unsigned int percent = 0;
 	unsigned int step = 0;


 	/*
 	 * Create a new channel to the server. The opened channel is
 	 * used to download the SWU
 	 */
 	channel_t *channel = channel_new();
 	if (!channel)
 		return NULL;

 	if (channel->open(channel, &channel_data) != CHANNEL_OK) {
 		channel->close(channel);
 		free(channel);
 		return NULL;
 	}

 	for (;;) {
 		ipc_message msg;
 		bool data_avail = false;
 		int ret = ipc_get_status(&msg);

 		if (ret < 0) {
 			ERROR("Error getting status, stopping notification thread");
-			stop = true;;
+			stop = true;
 		} else {
 			data_avail = (strlen(msg.data.status.desc) != 0);
 		}

 		/*
 		 * Mutex used to synchronize end of the thread
 		 * The suricatta thread locks the mutex at the beginning
 		 * and release it when this task should terminate.
 		 * By getting the lock, this task loads know it has to finish
 		 */
 		if (!pthread_mutex_trylock(&notifylock)) {
 			stop = true;
 		}

 		if (data_avail && msg.data.status.current == PROGRESS)
 			continue;
 		if (data_avail && numdetails < MAX_DETAILS) {
 			for (int c = 0; c < strlen(msg.data.status.desc); c++) {
 				switch (msg.data.status.desc[c]) {
 				case '"':
 				case '\'':
 				case '\\':
 				case '\n':
 				case '\r':
 					msg.data.status.desc[c] = ' ';
 					break;
 				}
 			}
 			details[numdetails++] = strdup(msg.data.status.desc);
 		}

 		/*
 		 * Flush to the server
 		 */
 		if (numdetails == MAX_DETAILS || (stop && !data_avail)) {
 			TRACE("Update log to server from thread");
 			if (server_send_deployment_reply(
 				channel,
 				action_id, step, percent,
 				reply_status_result_finished.none,
 				reply_status_execution.proceeding, numdetails,
 				&details[0]) != SERVER_OK) {
 				ERROR("Error while sending log to server.");
 			}
 			for (unsigned int count = 0; count < numdetails; count++) {
 				free((void *)details[count]);
 			}
 			numdetails = 0;
 			percent++;
 			if (percent > 100) {
 				percent = 0;
 				step++;
 			}
 		}

 		if (stop && !data_avail)
 			break;

 		// wait a bit for next message...
 		if (!data_avail)
 			usleep(100000);
 	}

 	pthread_mutex_unlock(&notifylock);

 	/*
 	 * Now close the channel for feedback
 	 */
 	channel->close(channel);
 	free(channel);

 	return NULL;
 }



